begin;
with j as (select * from jsonb_to_recordset($law7d0046$[{"code_id":"KONST_RF","article_number":"125","version_date":"1993-12-12","article_text":"1.Конституционный Суд Российской Федерации является высшим судебным органом конституционного контроля в Российской Федерации, осуществляющим судебную власть посредством конституционного судопроизводства в целях защиты основ конституционного строя, основных прав и свобод человека и гражданина, обеспечения верховенства и прямого действия Конституции Российской Федерации на всей территории Российской Федерации. Конституционный Суд Российской Федерации состоит из 11 судей, включая Председателя Конституционного Суда Российской Федерации и его заместителя.*\n\n2.Конституционный Суд Российской Федерации по запросам Президента Российской Федерации, Совета Федерации, Государственной Думы, одной пятой сенаторов Российской Федерации или депутатов Государственной Думы, Правительства Российской Федерации, Верховного Суда Российской Федерации, органов законодательной и исполнительной власти субъектов Российской Федерации разрешает дела о соответствии Конституции Российской Федерации:*\n\nа)федеральных конституционных законов, федеральных законов, нормативных актов Президента Российской Федерации, Совета Федерации, Государственной Думы, Правительства Российской Федерации;*\n\nб)конституций республик, уставов, а также законов и иных нормативных актов субъектов Российской Федерации, изданных по вопросам, относящимся к ведению органов государственной власти Российской Федерации и совместному ведению органов государственной власти Российской Федерации и органов государственной власти субъектов Российской Федерации;*\n\nв)договоров между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, договоров между органами государственной власти субъектов Российской Федерации;*\n\nг)не вступивших в силу международных договоров Российской Федерации.*\n\n3.Конституционный Суд Российской Федерации разрешает споры о компетенции:\n\nа)между федеральными органами государственной власти;\n\nб)между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации;\n\nв)между высшими государственными органами субъектов Российской Федерации.\n\n4.Конституционный Суд Российской Федерации в порядке, установленном федеральным конституционным законом, проверяет:*\n\nа)по жалобам на нарушение конституционных прав и свобод граждан — конституционность законов и иных нормативных актов, указанных в пунктах «а» и «б» части 2 настоящей статьи, примененных в конкретном деле, если исчерпаны все другие внутригосударственные средства судебной защиты;*\n\nб)по запросам судов — конституционность законов и иных нормативных актов, указанных в пунктах «а» и «б» части 2 настоящей статьи, подлежащих применению в конкретном деле.*\n\n5.Конституционный Суд Российской Федерации по запросам Президента Российской Федерации, Совета Федерации, Государственной Думы, Правительства Российской Федерации, органов законодательной власти субъектов Российской Федерации дает толкование Конституции Российской Федерации.\n\n51.Конституционный Суд Российской Федерации:\n\nа)по запросу Президента Российской Федерации проверяет конституционность проектов законов Российской Федерации о поправке к Конституции Российской Федерации, проектов федеральных конституционных законов и федеральных законов, а также принятых в порядке, предусмотренном частями 2 и 3 статьи 107 и частью 2 статьи 108 Конституции Российской Федерации, законов до их подписания Президентом Российской Федерации;\n\nб)в порядке, установленном федеральным конституционным законом, разрешает вопрос о возможности исполнения решений межгосударственных органов, принятых на основании положений международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации, а также о возможности исполнения решения иностранного или  международного (межгосударственного) суда, иностранного или международного третейского суда (арбитража), налагающего обязанности на Российскую Федерацию, в случае если это решение противоречит основам публичного правопорядка Российской Федерации;\n\nв)по запросу Президента Российской Федерации в порядке, установленном федеральным конституционным законом, проверяет конституционность законов субъекта Российской Федерации до их обнародования высшим должностным лицом субъекта Российской Федерации (руководителем высшего исполнительного органа государственной власти субъекта Российской Федерации).*\n\n6.Акты или их отдельные положения, признанные неконституционными, утрачивают силу; не соответствующие Конституции Российской Федерации международные договоры Российской Федерации не подлежат введению в действие и применению. Акты или их отдельные положения, признанные конституционными в истолковании, данном Конституционным Судом Российской Федерации, не подлежат применению в ином истолковании.*\n\n7.Конституционный Суд Российской Федерации по запросу Совета Федерации дает заключение о соблюдении установленного порядка выдвижения обвинения Президента Российской Федерации либо Президента Российской Федерации, прекратившего исполнение своих полномочий, в государственной измене или совершении иного тяжкого преступления.*\n\n8.Конституционный Суд Российской Федерации осуществляет иные полномочия, установленные федеральным конституционным законом.*","article_title":"Статья 125","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f4a5b83738ea985067e3cb92e756f3ed243a78d345b08b902e6f59357a9dc9b"},{"code_id":"KONST_RF","article_number":"126","version_date":"1993-12-12","article_text":"Верховный Суд Российской Федерации является высшим судебным органом по гражданским делам, разрешению экономических споров, уголовным, административным и иным делам, подсудным судам общей юрисдикции и арбитражным судам, образованным в соответствии с федеральным конституционным законом и осуществляющим судебную власть посредством гражданского, арбитражного, административного и уголовного судопроизводства. Верховный Суд Российской Федерации осуществляет в предусмотренных федеральным законом процессуальных формах судебный надзор за деятельностью судов общей юрисдикции и арбитражных судов и дает разъяснения по вопросам судебной практики.","article_title":"Статья 126","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06a4a3232e7bb9b110dae4d1d4bc93357bee5c1b89747eadf0f5f93d0714ebbc"},{"code_id":"KONST_RF","article_number":"127","version_date":"1993-12-12","article_text":"Исключена поправкой к Конституции Российской Федерации (Закон Российской Федерации о поправке к Конституции Российской Федерации «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации»).\n\nСтатья 127 исключена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).","article_title":"Статья 127","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50e76b2b29be44151d83f48561bb3fbce6850496edfbb9c4c98b0ad24dbb9cc7"},{"code_id":"KONST_RF","article_number":"128","version_date":"1993-12-12","article_text":"1.Председатель Конституционного Суда Российской Федерации, заместитель Председателя Конституционного Суда Российской Федерации и судьи Конституционного Суда Российской Федерации, Председатель Верховного Суда Российской Федерации, заместители Председателя Верховного Суда Российской Федерации и судьи Верховного Суда Российской Федерации назначаются Советом Федерации по представлению Президента Российской Федерации.\n\n2.Председатели, заместители председателей и судьи других федеральных судов назначаются Президентом Российской Федерации в порядке, установленном федеральным конституционным законом.\n\n3.Полномочия, порядок образования и деятельности Конституционного Суда Российской Федерации, Верховного Суда Российской Федерации и иных федеральных судов устанавливаются Конституцией Российской Федерации и федеральным конституционным законом. Порядок осуществления гражданского, арбитражного, административного и уголовного судопроизводства регулируется также соответствующим процессуальным законодательством.","article_title":"Статья 128","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee76b59a7ba7e4fc16f196fd0bd83ea8ce013023799badc5e382f72cf2be14f0"},{"code_id":"KONST_RF","article_number":"129","version_date":"1993-12-12","article_text":"1.Прокуратура Российской Федерации — единая федеральная централизованная система органов, осуществляющих надзор за соблюдением Конституции Российской Федерации и исполнением законов, надзор за соблюдением прав и свобод человека и гражданина, уголовное преследование в соответствии со своими полномочиями, а также выполняющих иные функции. Полномочия и функции прокуратуры Российской Федерации, ее организация и порядок деятельности определяются федеральным законом.\n\n2.Прокурорами могут быть граждане Российской Федерации, не имеющие гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Прокурорам в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n3.Генеральный прокурор Российской Федерации, заместители Генерального прокурора Российской Федерации назначаются на должность после консультаций с Советом Федерации и освобождаются от должности Президентом Российской Федерации.\n\n4.Прокуроры субъектов Российской Федерации, прокуроры военных и других специализированных прокуратур, приравненные к прокурорам субъектов Российской Федерации, назначаются на должность после консультаций с Советом Федерации и освобождаются от должности Президентом Российской Федерации.\n\n5.Иные прокуроры могут назначаться на должность и освобождаться от должности Президентом Российской Федерации, если такой порядок назначения на должность и освобождения от должности установлен федеральным законом.\n\n6.Если иное не предусмотрено федеральным законом, прокуроры городов, районов и приравненные к ним прокуроры назначаются на должность и освобождаются от должности Генеральным прокурором Российской Федерации.","article_title":"Статья 129","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cea44d4f644aaf96e98bca06bf58dc53b5bb296ce758581c64ce9c98d10206a"},{"code_id":"KONST_RF","article_number":"13","version_date":"1993-12-12","article_text":"1.В Российской Федерации признается идеологическое многообразие.\n\n2.Никакая идеология не может устанавливаться в качестве государственной или обязательной.\n\n3.В Российской Федерации признаются политическое многообразие, многопартийность.\n\n4.Общественные объединения равны перед законом.\n\n5.Запрещается создание и деятельность общественных объединений, цели или действия которых направлены на насильственное изменение основ конституционного строя и нарушение целостности Российской Федерации, подрыв безопасности государства, создание вооруженных формирований, разжигание социальной, расовой, национальной и религиозной розни.","article_title":"Статья 13","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ec14e72812ddb770c91f66ef955068c5fe3af499736a53f4a7b010edae97d04"},{"code_id":"KONST_RF","article_number":"130","version_date":"1993-12-12","article_text":"1.Местное самоуправление в Российской Федерации обеспечивает самостоятельное решение населением вопросов местного значения, владение, пользование и распоряжение муниципальной собственностью.\n\n2.Местное самоуправление осуществляется гражданами путем референдума, выборов, других форм прямого волеизъявления, через выборные и другие органы местного самоуправления.","article_title":"Статья 130","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3685a95696b34374ddeb538affc046436a96152f4a1909649548968b23ab342c"},{"code_id":"KONST_RF","article_number":"131","version_date":"1993-12-12","article_text":"1.Местное самоуправление осуществляется в муниципальных образованиях, виды которых устанавливаются федеральным законом. Территории муниципальных образований определяются с учетом исторических и иных местных традиций. Структура органов местного самоуправления определяется населением самостоятельно в соответствии с общими принципами организации местного самоуправления в Российской Федерации, установленными федеральным законом.*\n\n11.Органы государственной власти могут участвовать в формировании органов местного самоуправления, назначении на должность и освобождении от должности должностных лиц местного самоуправления в порядке и случаях, установленных федеральным законом.*\n\n2.Изменение границ территорий, в пределах которых осуществляется местное самоуправление, допускается с учетом мнения населения соответствующих территорий в порядке, установленном федеральным законом.*\n\n3.Особенности осуществления публичной власти на территориях городов федерального значения, административных центров (столиц) субъектов Российской Федерации и на других территориях могут устанавливаться федеральным законом.*","article_title":"Статья 131","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b390fca3178a0c70c6aa3c90e98c7039ad7a09958561178b6ced47970043f0c7"},{"code_id":"KONST_RF","article_number":"132","version_date":"1993-12-12","article_text":"1.Органы местного самоуправления самостоятельно управляют муниципальной собственностью, формируют, утверждают и исполняют местный бюджет, вводят местные налоги и сборы, решают иные вопросы местного значения, а также в соответствии с федеральным законом обеспечивают в пределах своей компетенции доступность медицинской помощи.*\n\n2.Органы местного самоуправления могут наделяться федеральным законом, законом субъекта Российской Федерации отдельными государственными полномочиями при условии передачи им необходимых для осуществления таких полномочий материальных и финансовых средств. Реализация переданных полномочий подконтрольна государству.*\n\n3.Органы местного самоуправления и органы государственной власти входят в единую систему публичной власти в Российской Федерации и осуществляют взаимодействие для наиболее эффективного решения задач в интересах населения, проживающего на соответствующей территории.*","article_title":"Статья 132","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b5a65066d6e6534434773f642ab2d943f5e13d2f7d5e32dde194c54af565d0b"},{"code_id":"KONST_RF","article_number":"133","version_date":"1993-12-12","article_text":"Местное самоуправление в Российской Федерации гарантируется правом на судебную защиту, на компенсацию дополнительных расходов, возникших в результате выполнения органами местного самоуправления во взаимодействии с органами государственной власти публичных функций, а также запретом на ограничение прав местного самоуправления, установленных Конституцией Российской Федерации и федеральными законами.","article_title":"Статья 133","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55cb5a2e933e4111282bc669ab6f71590c877b81fdd9a69b9c76ee79c537200d"},{"code_id":"KONST_RF","article_number":"134","version_date":"1993-12-12","article_text":"Предложения о поправках и пересмотре положений Конституции Российской Федерации могут вносить Президент Российской Федерации, Совет Федерации, Государственная Дума, Правительство Российской Федерации, законодательные(представительные) органы субъектов Российской Федерации, а также группа численностью не менее одной пятой членов Совета Федерации или депутатов Государственной Думы.","article_title":"Статья 134","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3045b8c0db621c56a9e4ddfc4fa8407fb1416b9186900e7c9a203de8d5b96405"},{"code_id":"KONST_RF","article_number":"135","version_date":"1993-12-12","article_text":"1.Положения глав 1, 2 и 9 Конституции Российской Федерации не могут быть пересмотрены Федеральным Собранием.\n\n2.Если предложение о пересмотре положений глав 1, 2 и 9 Конституции Российской Федерации будет поддержано тремя пятыми голосов от общего числа членов Совета Федерации и депутатов Государственной Думы, то в соответствии с федеральным конституционным законом созывается Конституционное Собрание.\n\n3.Конституционное Собрание либо подтверждает неизменность Конституции Российской Федерации, либо разрабатывает проект новой Конституции Российской Федерации, который принимается Конституционным Собранием двумя третями голосов от общего числа его членов или выносится на всенародное голосование. При проведении всенародного голосования Конституция Российской Федерации считается принятой, если за нее проголосовало более половины избирателей, принявших участие в голосовании, при условии, что в нем приняло участие более половины избирателей.","article_title":"Статья 135","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d4a7f7b6ec64f3e8c2fcdaf066120bfa0914113ce54ee154da623a8c37cbe5ac"},{"code_id":"KONST_RF","article_number":"136","version_date":"1993-12-12","article_text":"Поправки к главам 3 — 8 Конституции Российской Федерации принимаются в порядке, предусмотренном для принятия федерального конституционного закона, и вступают в силу после их одобрения органами законодательной власти не менее чем двух третей субъектов Российской Федерации.","article_title":"Статья 136","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecba3f388c9019bbe1e7a2df448bc95b3550c77d3bec48cb3b66e6198ca7a346"},{"code_id":"KONST_RF","article_number":"137","version_date":"1993-12-12","article_text":"1.Изменения в статью 65 Конституции Российской Федерации, определяющую состав Российской Федерации, вносятся на основании федерального конституционного закона о принятии в Российскую Федерацию и образовании в ее составе нового субъекта Российской Федерации, об изменении конституционно-правового статуса субъекта Российской Федерации.\n\n2.В случае изменения наименования республики, края, области, города федерального значения, автономной области, автономного округа новое наименование субъекта Российской Федерации подлежит включению в статью 65 Конституции Российской Федерации.","article_title":"Статья 137","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dada045b7107f640e8319afb03aa22f565a12ed0de897ad6fecd18a942aaa93"},{"code_id":"KONST_RF","article_number":"14","version_date":"1993-12-12","article_text":"1.Российская Федерация — светское государство. Никакая религия не может устанавливаться в качестве государственной или обязательной.\n\n2.Религиозные объединения отделены от государства и равны перед законом.","article_title":"Статья 14","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1548e1bc2830f017864579caf5b8b3ea8d337e1bcb37a3040e197e5cb129297"},{"code_id":"KONST_RF","article_number":"15","version_date":"1993-12-12","article_text":"1.Конституция Российской Федерации имеет высшую юридическую силу, прямое действие и применяется на всей территории Российской Федерации. Законы и иные правовые акты, принимаемые в Российской Федерации, не должны противоречить Конституции Российской Федерации.\n\n2.Органы государственной власти, органы местного самоуправления, должностные лица, граждане и их объединения обязаны соблюдать Конституцию Российской Федерации и законы.\n\n3.Законы подлежат официальному опубликованию. Неопубликованные законы не применяются. Любые нормативные правовые акты, затрагивающие права, свободы и обязанности человека и гражданина, не могут применяться, если они не опубликованы официально для всеобщего сведения.\n\n4.Общепризнанные принципы и нормы международного права и международные договоры Российской Федерации являются составной частью ее правовой системы. Если международным договором Российской Федерации установлены иные правила, чем предусмотренные законом, то применяются правила международного договора.","article_title":"Статья 15","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"958d8524aa72f9fa643c8763768210fc8ac5d89f3be52d39dff3a34adfccacf5"},{"code_id":"KONST_RF","article_number":"16","version_date":"1993-12-12","article_text":"1.Положения настоящей главы Конституции составляют основы конституционного строя Российской Федерации и не могут быть изменены иначе как в порядке, установленном настоящей Конституцией.\n\n2.Никакие другие положения настоящей Конституции не могут противоречить основам конституционного строя Российской Федерации.","article_title":"Статья 16","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1171e46737e4585b9a1bfc5a36a29f80d4c64dce780c78d505e47c152747193f"},{"code_id":"KONST_RF","article_number":"17","version_date":"1993-12-12","article_text":"1.В Российской Федерации признаются и гарантируются права и свободы человека и гражданина согласно общепризнанным принципам и нормам международного права и в соответствии с настоящей Конституцией.\n\n2.Основные права и свободы человека неотчуждаемы и принадлежат каждому от рождения.\n\n3.Осуществление прав и свобод человека и гражданина не должно нарушать права и свободы других лиц.","article_title":"Статья 17","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59a368abf382b5ca605ad000f03a961e4b7ea9bb7f2e3b4c2f9e5f1cfdebaad"},{"code_id":"KONST_RF","article_number":"18","version_date":"1993-12-12","article_text":"Права и свободы человека и гражданина являются непосредственно действующими. Они определяют смысл, содержание и применение законов, деятельность законодательной и исполнительной власти, местного самоуправления и обеспечиваются правосудием.","article_title":"Статья 18","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a7dce7de628092a1a8514518c0ecffde4b41daf7ac11d6d68aa1e59efb19817"},{"code_id":"KONST_RF","article_number":"19","version_date":"1993-12-12","article_text":"1.Все равны перед законом и судом.\n\n2.Государство гарантирует равенство прав и свобод человека и гражданина независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств. Запрещаются любые формы ограничения прав граждан по признакам социальной, расовой, национальной, языковой или религиозной принадлежности.\n\n3.Мужчина и женщина имеют равные права и свободы и равные возможности для их реализации.","article_title":"Статья 19","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29e22423d027492d8783086b6044c208ca9fd01a319e21adf96e9d89988ecd76"},{"code_id":"KONST_RF","article_number":"2","version_date":"1993-12-12","article_text":"Человек, его права и свободы являются высшей ценностью. Признание, соблюдение и защита прав и свобод человека и гражданина — обязанность государства.","article_title":"Статья 2","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5415fe27b68d848904b384bb9409ce2a7d5607f8c7597deafb5adaaac370819f"},{"code_id":"KONST_RF","article_number":"20","version_date":"1993-12-12","article_text":"1.Каждый имеет право на жизнь.\n\n2.Смертная казнь впредь до ее отмены может устанавливаться федеральным законом в качестве исключительной меры наказания за особо тяжкие преступления против жизни при предоставлении обвиняемому права на рассмотрение его дела судом с участием присяжных заседателей.","article_title":"Статья 20","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd881dd30ea2d850e0770ec8df37cde6ff9f8aaca071e5e7d7bd27dc72eba36c"},{"code_id":"KONST_RF","article_number":"21","version_date":"1993-12-12","article_text":"1.Достоинство личности охраняется государством. Ничто не может быть основанием для его умаления.\n\n2.Никто не должен подвергаться пыткам, насилию, другому жестокому или унижающему человеческое достоинство обращению или наказанию. Никто не может быть без добровольного согласия подвергнут медицинским, научным или иным опытам.","article_title":"Статья 21","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11191b06dd976d06a0d596284b77ec5b42725ca257bd0ca6c70c0c8a133a46b7"},{"code_id":"KONST_RF","article_number":"22","version_date":"1993-12-12","article_text":"1.Каждый имеет право на свободу и личную неприкосновенность.\n\n2.Арест, заключение под стражу и содержание под стражей допускаются только по судебному решению. До судебного решения лицо не может быть подвергнуто задержанию на срок более 48 часов.","article_title":"Статья 22","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"628dbfaf38053db3a09de9b0b765e5aeb1fa4a32ae7f1c37851e7426d2e4c89c"},{"code_id":"KONST_RF","article_number":"23","version_date":"1993-12-12","article_text":"1.Каждый имеет право на неприкосновенность частной жизни, личную и семейную тайну, защиту своей чести и доброго имени.\n\n2.Каждый имеет право на тайну переписки, телефонных переговоров, почтовых, телеграфных и иных сообщений. Ограничение этого права допускается только на основании судебного решения.","article_title":"Статья 23","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"515a42e3843c0693b545ae74568fc8f15d084b25ec2365be57b5e3058df2d49e"},{"code_id":"KONST_RF","article_number":"24","version_date":"1993-12-12","article_text":"1.Сбор, хранение, использование и распространение информации о частной жизни лица без его согласия не допускаются.\n\n2.Органы государственной власти и органы местного самоуправления, их должностные лица обязаны обеспечить каждому возможность ознакомления с документами и материалами, непосредственно затрагивающими его права и свободы, если иное не предусмотрено законом.","article_title":"Статья 24","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6389a41eae751d6f71be0257ce1e09f9065c6ea0527f3e4d77434040bc44f533"},{"code_id":"KONST_RF","article_number":"25","version_date":"1993-12-12","article_text":"Жилище неприкосновенно. Никто не вправе проникать в жилище против воли проживающих в нем лиц иначе как в случаях, установленных федеральным законом, или на основании судебного решения.","article_title":"Статья 25","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c14b91b512a98c77c4b8c377aecbb7a52e8565e7da4acb0205a7199bf3f66753"},{"code_id":"KONST_RF","article_number":"26","version_date":"1993-12-12","article_text":"1.Каждый вправе определять и указывать свою национальную принадлежность. Никто не может быть принужден к определению и указанию своей национальной принадлежности.\n\n2.Каждый имеет право на пользование родным языком, на свободный выбор языка общения, воспитания, обучения и творчества.","article_title":"Статья 26","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"160232a4eee30d05c38eefded4bd96498c8265afa7076992edccd602baa09d95"},{"code_id":"KONST_RF","article_number":"27","version_date":"1993-12-12","article_text":"1.Каждый, кто законно находится на территории Российской Федерации, имеет право свободно передвигаться, выбирать место пребывания и жительства.\n\n2.Каждый может свободно выезжать за пределы Российской Федерации. Гражданин Российской Федерации имеет право беспрепятственно возвращаться в Российскую Федерацию.","article_title":"Статья 27","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1286311c35bfca5ce9c11205fc394dc78de58a3ece1af8361584cddba95134b"},{"code_id":"KONST_RF","article_number":"28","version_date":"1993-12-12","article_text":"Каждому гарантируется свобода совести, свобода вероисповедания, включая право исповедовать индивидуально или совместно с другими любую религию или не исповедовать никакой, свободно выбирать, иметь и распространять религиозные и иные убеждения и действовать в соответствии с ними.","article_title":"Статья 28","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"070fc9943614b3e8d5e898dc2b082701359c77e1ffdd806229a18813d69de895"},{"code_id":"KONST_RF","article_number":"29","version_date":"1993-12-12","article_text":"1.Каждому гарантируется свобода мысли и слова.\n\n2.Не допускаются пропаганда или агитация, возбуждающие социальную, расовую, национальную или религиозную ненависть и вражду. Запрещается пропаганда социального, расового, национального, религиозного или языкового превосходства.\n\n3.Никто не может быть принужден к выражению своих мнений и убеждений или отказу от них.\n\n4.Каждый имеет право свободно искать, получать, передавать, производить и распространять информацию любым законным способом. Перечень сведений, составляющих государственную тайну, определяется федеральным законом.\n\n5.Гарантируется свобода массовой информации. Цензура запрещается.","article_title":"Статья 29","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97ad8805f147b36231feb706f5dbbc585c10fee97a8218f3abccc321965a2b30"},{"code_id":"KONST_RF","article_number":"3","version_date":"1993-12-12","article_text":"1.Носителем суверенитета и единственным источником власти в Российской Федерации является ее многонациональный народ.\n\n2.Народ осуществляет свою власть непосредственно, а также через органы государственной власти и органы местного самоуправления.\n\n3.Высшим непосредственным выражением власти народа являются референдум и свободные выборы.\n\n4.Никто не может присваивать власть в Российской Федерации. Захват власти или присвоение властных полномочий преследуются по федеральному закону.","article_title":"Статья 3","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb5783197b5f00871af588b8ea4972fc12e5ac1a10f712ea2822dbb24d292190"},{"code_id":"KONST_RF","article_number":"30","version_date":"1993-12-12","article_text":"1.Каждый имеет право на объединение, включая право создавать профессиональные союзы для защиты своих интересов. Свобода деятельности общественных объединений гарантируется.\n\n2.Никто не может быть принужден к вступлению в какое-либо объединение или пребыванию в нем.","article_title":"Статья 30","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f17112d46ac6a71c60c7bdcf0db77d5e8a25748778b0d76a14d5fb478d463da"},{"code_id":"KONST_RF","article_number":"31","version_date":"1993-12-12","article_text":"Граждане Российской Федерации имеют право собираться мирно, без оружия, проводить собрания, митинги и демонстрации, шествия и пикетирование.","article_title":"Статья 31","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e04d324cb4447c8020911793af4359a38a2a6686f87317ee3a61a7e13325793"},{"code_id":"KONST_RF","article_number":"32","version_date":"1993-12-12","article_text":"1.Граждане Российской Федерации имеют право участвовать в управлении делами государства как непосредственно, так и через своих представителей.\n\n2.Граждане Российской Федерации имеют право избирать и быть избранными в органы государственной власти и органы местного самоуправления, а также участвовать в референдуме.\n\n3.Не имеют права избирать и быть избранными граждане, признанные судом недееспособными, а также содержащиеся в местах лишения свободы по приговору суда.\n\n4.Граждане Российской Федерации имеют равный доступ к государственной службе.\n\n5.Граждане Российской Федерации имеют право участвовать в отправлении правосудия.","article_title":"Статья 32","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c667640ac8ea2090f438ea835ca9307a0b489712d673ad04ae95e654ff3e3b"},{"code_id":"KONST_RF","article_number":"33","version_date":"1993-12-12","article_text":"Граждане Российской Федерации имеют право обращаться лично, а также направлять индивидуальные и коллективные обращения в государственные органы и органы местного самоуправления.","article_title":"Статья 33","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a94f8b4f76c8cd18494ca3c860fde285d0fe72db245bdfe4679cbfb3a00569c1"},{"code_id":"KONST_RF","article_number":"34","version_date":"1993-12-12","article_text":"1.Каждый имеет право на свободное использование своих способностей и имущества для предпринимательской и иной не запрещенной законом экономической деятельности.\n\n2.Не допускается экономическая деятельность, направленная на монополизацию и недобросовестную конкуренцию.","article_title":"Статья 34","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3650ea6720e04834bce9e70e5021de8b65d7f14354ea12377feae3e4ad202121"},{"code_id":"KONST_RF","article_number":"35","version_date":"1993-12-12","article_text":"1.Право частной собственности охраняется законом.\n\n2.Каждый вправе иметь имущество в собственности, владеть, пользоваться и распоряжаться им как единолично, так и совместно с другими лицами.\n\n3.Никто не может быть лишен своего имущества иначе как по решению суда. Принудительное отчуждение имущества для государственных нужд может быть произведено только при условии предварительного и равноценного возмещения.\n\n4.Право наследования гарантируется.","article_title":"Статья 35","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad73a9e20eae648f05ab0da28e1cd132ecd16bb2e140cf206b1d08458202c9bc"},{"code_id":"KONST_RF","article_number":"36","version_date":"1993-12-12","article_text":"1.Граждане и их объединения вправе иметь в частной собственности землю.\n\n2.Владение, пользование и распоряжение землей и другими природными ресурсами осуществляются их собственниками свободно, если это не наносит ущерба окружающей среде и не нарушает прав и законных интересов иных лиц.\n\n3.Условия и порядок пользования землей определяются на основе федерального закона.","article_title":"Статья 36","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86dabaf833dab5fb6dfe61ff161aab2812fb06718257d2fa7a3e3019c0175fd2"},{"code_id":"KONST_RF","article_number":"37","version_date":"1993-12-12","article_text":"1.Труд свободен. Каждый имеет право свободно распоряжаться своими способностями к труду, выбирать род деятельности и профессию.\n\n2.Принудительный труд запрещен.\n\n3.Каждый имеет право на труд в условиях, отвечающих требованиям безопасности и гигиены, на вознаграждение за труд без какой бы то ни было дискриминации и не ниже установленного федеральным законом минимального размера оплаты труда, а также право на защиту от безработицы.\n\n4.Признается право на индивидуальные и коллективные трудовые споры с использованием установленных федеральным законом способов их разрешения, включая право на забастовку.\n\n5.Каждый имеет право на отдых. Работающему по трудовому договору гарантируются установленные федеральным законом продолжительность рабочего времени, выходные и праздничные дни, оплачиваемый ежегодный отпуск.","article_title":"Статья 37","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9dce34591f6fb0a43ecf0f0b1addde451809096b238bea31af3798e4c047e81"},{"code_id":"KONST_RF","article_number":"38","version_date":"1993-12-12","article_text":"1.Материнство и детство, семья находятся под защитой государства.\n\n2.Забота о детях, их воспитание — равное право и обязанность родителей.\n\n3.Трудоспособные дети, достигшие 18 лет, должны заботиться о нетрудоспособных родителях.","article_title":"Статья 38","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b9a767d510e9b327afefbe47c9c769f8d1c64257e6a356dfb0a1b18e7bb3d89"},{"code_id":"KONST_RF","article_number":"39","version_date":"1993-12-12","article_text":"1.Каждому гарантируется социальное обеспечение по возрасту, в случае болезни, инвалидности, потери кормильца, для воспитания детей и в иных случаях, установленных законом.\n\n2.Государственные пенсии и социальные пособия устанавливаются законом.\n\n3.Поощряются добровольное социальное страхование, создание дополнительных форм социального обеспечения и благотворительность.","article_title":"Статья 39","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0aaff46f40291641d325fce8b2f467811948bc0661adf5b3945691b7cc13d847"},{"code_id":"KONST_RF","article_number":"4","version_date":"1993-12-12","article_text":"1.Суверенитет Российской Федерации распространяется на всю ее территорию.\n\n2.Конституция Российской Федерации и федеральные законы имеют верховенство на всей территории Российской Федерации.\n\n3.Российская Федерация обеспечивает целостность и неприкосновенность своей территории.","article_title":"Статья 4","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"425cd544012f7ebf10de9f5dff54d233af1d008e9a936ed0581beea85235609f"},{"code_id":"KONST_RF","article_number":"40","version_date":"1993-12-12","article_text":"1.Каждый имеет право на жилище. Никто не может быть произвольно лишен жилища.\n\n2.Органы государственной власти и органы местного самоуправления поощряют жилищное строительство, создают условия для осуществления права на жилище.\n\n3.Малоимущим, иным указанным в законе гражданам, нуждающимся в жилище, оно предоставляется бесплатно или за доступную плату из государственных, муниципальных и других жилищных фондов в соответствии с установленными законом нормами.","article_title":"Статья 40","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"deb2e91189a59f17ec12bac8115adbd36da0aec6879bb54eea176c8a6cc45134"},{"code_id":"KONST_RF","article_number":"41","version_date":"1993-12-12","article_text":"1.Каждый имеет право на охрану здоровья и медицинскую помощь. Медицинская помощь в государственных и муниципальных учреждениях здравоохранения оказывается гражданам бесплатно за счет средств соответствующего бюджета, страховых взносов, других поступлений.\n\n2.В Российской Федерации финансируются федеральные программы охраны и укрепления здоровья населения, принимаются меры по развитию государственной, муниципальной, частной систем здравоохранения, поощряется деятельность, способствующая укреплению здоровья человека, развитию физической культуры и спорта, экологическому и санитарно-эпидемиологическому благополучию.\n\n3.Сокрытие должностными лицами фактов и обстоятельств, создающих угрозу для жизни и здоровья людей, влечет за собой ответственность в соответствии с федеральным законом.","article_title":"Статья 41","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d51b2de8b078b0e6e97cf1cb489b331d8eb69ae5493c1d95b61278b241b86e56"},{"code_id":"KONST_RF","article_number":"42","version_date":"1993-12-12","article_text":"Каждый имеет право на благоприятную окружающую среду, достоверную информацию о ее состоянии и на возмещение ущерба, причиненного его здоровью или имуществу экологическим правонарушением.","article_title":"Статья 42","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"102ca3c138f1ef7865f1bb7f543af44d362ee8a62e7bd9ad0ab450b14750c464"},{"code_id":"KONST_RF","article_number":"43","version_date":"1993-12-12","article_text":"1.Каждый имеет право на образование.\n\n2.Гарантируются общедоступность и бесплатность дошкольного, основного общего и среднего профессионального образования в государственных или муниципальных образовательных учреждениях и на предприятиях.\n\n3.Каждый вправе на конкурсной основе бесплатно получить высшее образование в государственном или муниципальном образовательном учреждении и на предприятии.\n\n4.Основное общее образование обязательно. Родители или лица, их заменяющие, обеспечивают получение детьми основного общего образования.\n\n5.Российская Федерация устанавливает федеральные государственные образовательные стандарты, поддерживает различные формы образования и самообразования.","article_title":"Статья 43","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be3200f4fa74b472361d8e7ffd3af242a93f381a5f23798cfe98873aa30ef72f"},{"code_id":"KONST_RF","article_number":"44","version_date":"1993-12-12","article_text":"1.Каждому гарантируется свобода литературного, художественного, научного, технического и других видов творчества, преподавания. Интеллектуальная собственность охраняется законом.\n\n2.Каждый имеет право на участие в культурной жизни и пользование учреждениями культуры, на доступ к культурным ценностям.\n\n3.Каждый обязан заботиться о сохранении исторического и культурного наследия, беречь памятники истории и культуры.","article_title":"Статья 44","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd931868ace2a7fc9608f18fc87c7c5f1e5a352ae32666e8fcb295cc1ca3ec8e"},{"code_id":"KONST_RF","article_number":"45","version_date":"1993-12-12","article_text":"1.Государственная защита прав и свобод человека и гражданина в Российской Федерации гарантируется.\n\n2.Каждый вправе защищать свои права и свободы всеми способами, не запрещенными законом.","article_title":"Статья 45","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79be89ee0f27ea513fed4bbc30f525982d0c283d4ac57ffea4ee6104220e38cf"},{"code_id":"KONST_RF","article_number":"46","version_date":"1993-12-12","article_text":"1.Каждому гарантируется судебная защита его прав и свобод.\n\n2.Решения и действия(или бездействие) органов государственной власти, органов местного самоуправления, общественных объединений и должностных лиц могут быть обжалованы в суд.\n\n3.Каждый вправе в соответствии с международными договорами Российской Федерации обращаться в межгосударственные органы по защите прав и свобод человека, если исчерпаны все имеющиеся внутригосударственные средства правовой защиты.","article_title":"Статья 46","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dc2bc180552078a5642ec21de8dae02f507d32787f8811520ad749954362af1"},{"code_id":"KONST_RF","article_number":"47","version_date":"1993-12-12","article_text":"1.Никто не может быть лишен права на рассмотрение его дела в том суде и тем судьей, к подсудности которых оно отнесено законом.\n\n2.Обвиняемый в совершении преступления имеет право на рассмотрение его дела судом с участием присяжных заседателей в случаях, предусмотренных федеральным законом.","article_title":"Статья 47","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5f98e64f5289d3e7e88bc20a8ea755193daf6f54015df51a6e97975355204d2"},{"code_id":"KONST_RF","article_number":"48","version_date":"1993-12-12","article_text":"1.Каждому гарантируется право на получение квалифицированной юридической помощи. В случаях, предусмотренных законом, юридическая помощь оказывается бесплатно.\n\n2.Каждый задержанный, заключенный под стражу, обвиняемый в совершении преступления имеет право пользоваться помощью адвоката(защитника) с момента соответственно задержания, заключения под стражу или предъявления обвинения.","article_title":"Статья 48","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7dcc5273d82d12dc4eeee9cba52589c77a613e511adc41552e70361aa6f7dac"},{"code_id":"KONST_RF","article_number":"49","version_date":"1993-12-12","article_text":"1.Каждый обвиняемый в совершении преступления считается невиновным, пока его виновность не будет доказана в предусмотренном федеральным законом порядке и установлена вступившим в законную силу приговором суда.\n\n2.Обвиняемый не обязан доказывать свою невиновность.\n\n3.Неустранимые сомнения в виновности лица толкуются в пользу обвиняемого.","article_title":"Статья 49","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26b0f2d6af4f9988c96c7f5fd03a335f99e08202677d4bee005291bb1668fce4"},{"code_id":"KONST_RF","article_number":"5","version_date":"1993-12-12","article_text":"1.Российская Федерация состоит из республик, краев, областей, городов федерального значения, автономной области, автономных округов — равноправных субъектов Российской Федерации.\n\n2.Республика(государство) имеет свою конституцию и законодательство. Край, область, город федерального значения, автономная область, автономный округ имеет свой устав и законодательство.\n\n3.Федеративное устройство Российской Федерации основано на ее государственной целостности, единстве системы государственной власти, разграничении предметов ведения и полномочий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, равноправии и самоопределении народов в Российской Федерации.\n\n4.Во взаимоотношениях с федеральными органами государственной власти все субъекты Российской Федерации между собой равноправны.","article_title":"Статья 5","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f924511a845ba922d9a51b037766319860acd08f379b9ac164a9d3ceecd79b87"},{"code_id":"KONST_RF","article_number":"50","version_date":"1993-12-12","article_text":"1.Никто не может быть повторно осужден за одно и то же преступление.\n\n2.При осуществлении правосудия не допускается использование доказательств, полученных с нарушением федерального закона.\n\n3.Каждый осужденный за преступление имеет право на пересмотр приговора вышестоящим судом в порядке, установленном федеральным законом, а также право просить о помиловании или смягчении наказания.","article_title":"Статья 50","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b749116841077ce1fabc4625f073dfacd91f11b59b762002032ae560189fe49b"},{"code_id":"KONST_RF","article_number":"51","version_date":"1993-12-12","article_text":"1.Никто не обязан свидетельствовать против себя самого, своего супруга и близких родственников, круг которых определяется федеральным законом.\n\n2.Федеральным законом могут устанавливаться иные случаи освобождения от обязанности давать свидетельские показания.","article_title":"Статья 51","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af047289203d56a2ff98d564c9059347e11f6ffa8eaf1e524d0e721afbe323c7"},{"code_id":"KONST_RF","article_number":"52","version_date":"1993-12-12","article_text":"Права потерпевших от преступлений и злоупотреблений властью охраняются законом. Государство обеспечивает потерпевшим доступ к правосудию и компенсацию причиненного ущерба.","article_title":"Статья 52","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05412ad0d1b877903ad03ffc9adaf1189750b5d978c1084abf39a3f725da293c"},{"code_id":"KONST_RF","article_number":"53","version_date":"1993-12-12","article_text":"Каждый имеет право на возмещение государством вреда, причиненного незаконными действиями(или бездействием) органов государственной власти или их должностных лиц.","article_title":"Статья 53","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"971199fd5d2559708d3ccd85e146eabe8bc415558e55337aeb69939a16672530"},{"code_id":"KONST_RF","article_number":"54","version_date":"1993-12-12","article_text":"1.Закон, устанавливающий или отягчающий ответственность, обратной силы не имеет.\n\n2.Никто не может нести ответственность за деяние, которое в момент его совершения не признавалось правонарушением. Если после совершения правонарушения ответственность за него устранена или смягчена, применяется новый закон.","article_title":"Статья 54","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ebd9bba6829efd2f36b450c7393743b0a6c31d3a0d531d0f11959142971db818"},{"code_id":"KONST_RF","article_number":"55","version_date":"1993-12-12","article_text":"1.Перечисление в Конституции Российской Федерации основных прав и свобод не должно толковаться как отрицание или умаление других общепризнанных прав и свобод человека и гражданина.\n\n2.В Российской Федерации не должны издаваться законы, отменяющие или умаляющие права и свободы человека и гражданина.\n\n3.Права и свободы человека и гражданина могут быть ограничены федеральным законом только в той мере, в какой это необходимо в целях защиты основ конституционного строя, нравственности, здоровья, прав и законных интересов других лиц, обеспечения обороны страны и безопасности государства.","article_title":"Статья 55","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c13b22b8cf8892d2076e8dc76614d52ca59bb186be8975f17987369f07ac629e"},{"code_id":"KONST_RF","article_number":"56","version_date":"1993-12-12","article_text":"1.В условиях чрезвычайного положения для обеспечения безопасности граждан и защиты конституционного строя в соответствии с федеральным конституционным законом могут устанавливаться отдельные ограничения прав и свобод с указанием пределов и срока их действия.\n\n2.Чрезвычайное положение на всей территории Российской Федерации и в ее отдельных местностях может вводиться при наличии обстоятельств и в порядке, установленных федеральным конституционным законом.\n\n3.Не подлежат ограничению права и свободы, предусмотренные статьями 20, 21, 23(часть 1), 24, 28, 34(часть 1), 40(часть 1), 46 — 54 Конституции Российской Федерации.","article_title":"Статья 56","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08fdcf481862283107f37e1b38c31c26cb2f6b36e6adbcec1483f4ce6a0b6b53"},{"code_id":"KONST_RF","article_number":"57","version_date":"1993-12-12","article_text":"Каждый обязан платить законно установленные налоги и сборы. Законы, устанавливающие новые налоги или ухудшающие положение налогоплательщиков, обратной силы не имеют.","article_title":"Статья 57","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"32b921b95909074032e58069b05396f65b01decec310484564bbac374534ea16"},{"code_id":"KONST_RF","article_number":"58","version_date":"1993-12-12","article_text":"Каждый обязан сохранять природу и окружающую среду, бережно относиться к природным богатствам.","article_title":"Статья 58","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3698d5329a74d6de73c22fb9c604a03a570f8d73a3c17080afc1f80721d3ee4"},{"code_id":"KONST_RF","article_number":"59","version_date":"1993-12-12","article_text":"1.Защита Отечества является долгом и обязанностью гражданина Российской Федерации.\n\n2.Гражданин Российской Федерации несет военную службу в соответствии с федеральным законом.\n\n3.Гражданин Российской Федерации в случае, если его убеждениям или вероисповеданию противоречит несение военной службы, а также в иных установленных федеральным законом случаях имеет право на замену ее альтернативной гражданской службой.","article_title":"Статья 59","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4da6fbc79322eea45bf057a161a9287fb3a98562e8760f7bc6f2d568797ca98"},{"code_id":"KONST_RF","article_number":"6","version_date":"1993-12-12","article_text":"1.Гражданство Российской Федерации приобретается и прекращается в соответствии с федеральным законом, является единым и равным независимо от оснований приобретения.\n\n2.Каждый гражданин Российской Федерации обладает на ее территории всеми правами и свободами и несет равные обязанности, предусмотренные Конституцией Российской Федерации.\n\n3.Гражданин Российской Федерации не может быть лишен своего гражданства или права изменить его.","article_title":"Статья 6","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39924c734667f00993d48df5c5a25202a77a00007ca492e6c08751da57b2b1d8"},{"code_id":"KONST_RF","article_number":"60","version_date":"1993-12-12","article_text":"Гражданин Российской Федерации может самостоятельно осуществлять в полном объеме свои права и обязанности с 18 лет.","article_title":"Статья 60","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27e9987f653112542285d192f819134b14441e0ddf531acd0106f66dac26c035"},{"code_id":"KONST_RF","article_number":"61","version_date":"1993-12-12","article_text":"1.Гражданин Российской Федерации не может быть выслан за пределы Российской Федерации или выдан другому государству.\n\n2.Российская Федерация гарантирует своим гражданам защиту и покровительство за ее пределами.","article_title":"Статья 61","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76bc61af92e077ca015f5c023fa25519a6781eaa0c1eedd668592b32ddf5ccdf"},{"code_id":"KONST_RF","article_number":"62","version_date":"1993-12-12","article_text":"1.Гражданин Российской Федерации может иметь гражданство иностранного государства(двойное гражданство) в соответствии с федеральным законом или международным договором Российской Федерации.\n\n2.Наличие у гражданина Российской Федерации гражданства иностранного государства не умаляет его прав и свобод и не освобождает от обязанностей, вытекающих из российского гражданства, если иное не предусмотрено федеральным законом или международным договором Российской Федерации.\n\n3.Иностранные граждане и лица без гражданства пользуются в Российской Федерации правами и несут обязанности наравне с гражданами Российской Федерации, кроме случаев, установленных федеральным законом или международным договором Российской Федерации.","article_title":"Статья 62","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3578263482f3cdf0801d0301ad7d9d9012b386e952abc407419ad35c9f0170a2"},{"code_id":"KONST_RF","article_number":"63","version_date":"1993-12-12","article_text":"1.Российская Федерация предоставляет политическое убежище иностранным гражданам и лицам без гражданства в соответствии с общепризнанными нормами международного права.\n\n2.В Российской Федерации не допускается выдача другим государствам лиц, преследуемых за политические убеждения, а также за действия(или бездействие), не признаваемые в Российской Федерации преступлением. Выдача лиц, обвиняемых в совершении преступления, а также передача осужденных для отбывания наказания в других государствах осуществляются на основе федерального закона или международного договора Российской Федерации.","article_title":"Статья 63","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee06123ce7c87829aa996ababe00fd4e0834e0fbe2782420bbd7a0f7d118475f"},{"code_id":"KONST_RF","article_number":"64","version_date":"1993-12-12","article_text":"Положения настоящей главы составляют основы правового статуса личности в Российской Федерации и не могут быть изменены иначе как в порядке, установленном настоящей Конституцией.","article_title":"Статья 64","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"59b9890c954a0d1b9bed953ecadb18e3ef6c55141fd6dcd377f529e2eb758e84"},{"code_id":"KONST_RF","article_number":"65","version_date":"1993-12-12","article_text":"1.В составе Российской Федерации находятся субъекты Российской Федерации:\n\nРеспублика Адыгея(Адыгея), Республика Алтай, Республика Башкортостан, Республика Бурятия, Республика Дагестан,Донецкая Народная Республика,Республика Ингушетия, Кабардино-Балкарская Республика,Республика Калмыкия, Карачаево-Черкесская Республика, Республика Карелия, Республика Коми,Республика Крым,Луганская Народная Республика, Республика Марий Эл, Республика Мордовия, Республика Саха(Якутия),Республика Северная Осетия — Алания, Республика Татарстан(Татарстан), Республика Тыва, Удмуртская Республика, Республика Хакасия, Чеченская Республика, Чувашская Республика —Чувашия;\n\nРедакция статей, частей и пунктов, помеченных символом <*>, приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 14 марта 2020 г. № 1-ФКЗ «О совершенствовании регулирования отдельных вопросов организации и функционирования публичной власти». Изменения, внесенные названным Законом Российской Федерации о поправке к Конституции Российской Федерации, вступают в силу со дня официального опубликования результатов общероссийского голосования по вопросу одобрения изменений в Конституцию Российской Федерации.Наименование нового субъекта Российской Федерации - Донецкая Народная Республика - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 5-ФКЗ \"О принятии в Российскую Федерацию Донецкой Народной Республики и образовании в составе Российской Федерации нового субъекта - Донецкой Народной Республики\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050005).Новое наименование  Республики  дано в соответствии с Указом Президента Российской Федерации от 9 января 1996 г. № 20«О включении новых наименований субъектов Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 3, ст. 152).Новое наименование Республики дано в соответствии с Указом Президента Российской Федерации от 10 февраля 1996 г. № 173«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 7, ст. 676).Наименование нового субъекта Российской Федерации — Республика Крым — дано в соответствии с Федеральным конституционным законом от 21 марта 2014 г. № 6-ФКЗ«О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов — Республики Крым и города федерального значения Севастополя»(Собрание законодательства Российской Федерации, 2014, № 12, ст. 1201).Наименование нового субъекта Российской Федерации - Луганская Народная Республика - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 6-ФКЗ \"О принятии в Российскую Федерацию Луганской Народной Республики и образовании в составе Российской Федерации нового субъекта - Луганской Народной Республики\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050006).Новое наименование Республики дано в соответствии с Указом Президента Российской Федерации от 9 января 1996 г. № 20«О включении новых наименований субъектов Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 3, ст. 152).Новое наименование  Республики дано в соответствии с Указом Президента Российской Федерации от 9 июня 2001 г. № 679«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 2001, № 24, ст. 2421).\n\nАлтайский край,Забайкальский край,Камчатский край, Краснодарский край,Красноярский край,Пермский край, Приморский край, Ставропольский край, Хабаровский край;\n\nНаименование нового субъекта Российской Федерации — Забайкальский край — дано в связи с его образованием с 1 марта 2008 г., а наименования прекративших существование с 1 марта 2008 г. в качестве субъектов Российской Федерации Читинской области и Агинского Бурятского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 21 июля 2007 г. № 5-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Читинской области и Агинского Бурятского автономного округа»(Собрание законодательства Российской Федерации, 2007, № 30, ст. 3745).Новое наименование области дано в соответствии с Указом Президента Российской Федерации от 27 марта 2019 г. № 130 «О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации» (Собрание законодательства Российской Федерации, 2019, № 13, ст. 1390).Наименование нового субъекта Российской Федерации - Херсонская область - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 8-ФКЗ \"О принятии в Российскую Федерацию Херсонской области и образовании в составе Российской Федерации нового субъекта - Херсонской области\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050008).Наименование нового субъекта Российской Федерации — Камчатский край — дано в связи с его образованием с 1 июля 2007 г., а наименования прекративших существование с 1 июля 2007 г. в качестве субъектов Российской Федерации Камчатской области и Корякского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 12 июля 2006 г. № 2-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Камчатской области и Корякского автономного округа»(Собрание законодательства Российской Федерации, 2006, № 29, ст. 3119).Наименование нового субъекта Российской Федерации — Красноярский край — дано в связи с его образованием с 1 января 2007 г., а наименования прекративших существование с 1 января 2007 г. в качестве субъектов Российской Федерации Таймырского (Долгано-Ненецкого) автономного округа и Эвенкийского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 14 октября 2005 г. № 6-ФКЗ «Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Красноярского края, Таймырского (Долгано-Ненецкого) автономного округа и Эвенкийского автономного округа» (Собрание законодательства Российской Федерации, 2005, № 42, ст. 4212).Наименование нового субъекта Российской Федерации — Пермский край — дано в связи с его образованием с 1 декабря 2005 г., а наименования прекративших существование с 1 декабря 2005 г. в качестве субъектов Российской Федерации Пермской области и Коми-Пермяцкого автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 25 марта 2004 г. № 1-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Пермской области и Коми-Пермяцкого автономного округа»(Собрание законодательства Российской Федерации, 2004, № 13, ст. 1110).\n\nАмурская область, Архангельская область, Астраханская область, Белгородская область, Брянская область, Владимирская область, Волгоградская область, Вологодская область, Воронежская область,Запорожская область, Ивановская область,Иркутская область, Калининградская область, Калужская область,Кемеровская область — Кузбасс, Кировская область, Костромская область, Курганская область, Курская область, Ленинградская область, Липецкая область, Магаданская область, Московская область, Мурманская область, Нижегородская область, Новгородская область, Новосибирская область, Омская область, Оренбургская область, Орловская область, Пензенская область, Псковская область, Ростовская область, Рязанская область, Самарская область, Саратовская область, Сахалинская область, Свердловская область, Смоленская область, Тамбовская область, Тверская область, Томская область, Тульская область, Тюменская область, Ульяновская область,Херсонская область, Челябинская область, Ярославская область;\n\nНаименование нового субъекта Российской Федерации — Иркутская область — дано в связи с его образованием с 1 января 2008 г., а наименование прекратившего существование с 1 января 2008 г. в качестве субъекта Российской Федерации Усть-Ордынского Бурятского автономного округа исключено из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 30 декабря 2006 г. № 6-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Иркутской области и Усть-Ордынского Бурятского автономного округа»(Собрание законодательства Российской Федерации, 2007, № 1, ст. 1).Наименование нового субъекта Российской Федерации - Запорожская область - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 7-ФКЗ \"О принятии в Российскую Федерацию Запорожской области и образовании в составе Российской Федерации нового субъекта - Запорожской области\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050007).\n\nМосква, Санкт-Петербург,Севастополь— города федерального значения;\n\nНаименование нового субъекта Российской Федерации — город федерального значения Севастополь — дано в соответствии с Федеральным конституционным законом от 21 марта 2014 г. № 6-ФКЗ«О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов — Республики Крым и города федерального значения Севастополя»(Собрание законодательства Российской Федерации, 2014, № 12. ст. 1201).\n\nЕврейская автономная область;\n\nНенецкий автономный округ, Ханты-Мансийский автономныйокруг —Югра, Чукотский автономный округ, Ямало-Ненецкий автономный округ.\n\nНовое наименование автономного округа дано в соответствии с Указом Президента Российской Федерации от 25 июля 2003 г. № 841«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 2003, № 30. ст. 3051).\n\n2.Принятие в Российскую Федерацию и образование в ее составе нового субъекта осуществляются в порядке, установленном федеральным конституционным законом.","article_title":"Статья 65","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"435216e9dca146dc1d9dc81e9ac5ab4eac2410a9587885b4c6451aa282c81884"},{"code_id":"KONST_RF","article_number":"66","version_date":"1993-12-12","article_text":"1.Статус республики определяется Конституцией Российской Федерации и конституцией республики.\n\n2.Статус края, области, города федерального значения, автономной области, автономного округа определяется Конституцией Российской Федерации и уставом края, области, города федерального значения, автономной области, автономного округа, принимаемым законодательным(представительным) органом соответствующего субъекта Российской Федерации.\n\n3.По представлению законодательных и исполнительных органов автономной области, автономного округа может быть принят федеральный закон об автономной области, автономном округе.\n\n4.Отношения автономных округов, входящих в состав края или области, могут регулироваться федеральным законом и договором между органами государственной власти автономного округа и, соответственно, органами государственной власти края или области.\n\n5.Статус субъекта Российской Федерации может быть изменен по взаимному согласию Российской Федерации и субъекта Российской Федерации в соответствии с федеральным конституционным законом.","article_title":"Статья 66","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f1d7e8dee16602b96b2acb6038b7488b3d972e8b8cc700687626afe916750be"},{"code_id":"KONST_RF","article_number":"67","version_date":"1993-12-12","article_text":"1.Территория Российской Федерации включает в себя территории ее субъектов, внутренние воды и территориальное море, воздушное пространство над ними. На территории Российской Федерации в соответствии с федеральным законом могут быть созданы федеральные территории. Организация публичной власти на федеральных территориях устанавливается указанным федеральным законом.*\n\n2.Российская Федерация обладает суверенными правами и осуществляет юрисдикцию на континентальном шельфе и в исключительной экономической зоне Российской Федерации в порядке, определяемом федеральным законом и нормами международного права.\n\n21.Российская Федерация обеспечивает защиту своего суверенитета и территориальной целостности. Действия (за исключением делимитации, демаркации, редемаркации государственной границы Российской Федерации с сопредельными государствами), направленные на отчуждение части территории Российской Федерации, а также призывы к таким действиям не допускаются.*i\n\n3.Границы между субъектами Российской Федерации могут быть изменены с их взаимного согласия.","article_title":"Статья 67","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b59362f234cda1999e3db1e035a0479cb0dc3122e9a1f2de4fb424c5519a2101"},{"code_id":"KONST_RF","article_number":"68","version_date":"1993-12-12","article_text":"1.Государственным языком Российской Федерации на всей ее территории является русский язык как язык государствообразующего народа, входящего в многонациональный союз равноправных народов Российской Федерации.\n\n2.Республики вправе устанавливать свои государственные языки. В органах государственной власти, органах местного самоуправления, государственных учреждениях республик они употребляются наряду с государственным языком Российской Федерации.\n\n3.Российская Федерация гарантирует всем ее народам право на сохранение родного языка, создание условий для его изучения и развития.\n\n4.Культура в Российской Федерации является уникальным наследием ее многонационального народа. Культура поддерживается и охраняется государством.","article_title":"Статья 68","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59b905a0016ca53551a42e2f805e67a71e96827503b0483ae2d8b80bb640324"},{"code_id":"KONST_RF","article_number":"69","version_date":"1993-12-12","article_text":"1.Российская Федерация гарантирует права коренных малочисленных народов в соответствии с общепризнанными принципами и нормами международного права и международными договорами Российской Федерации.\n\n2.Государство защищает культурную самобытность всех народов и этнических общностей Российской Федерации, гарантирует сохранение этнокультурного и языкового многообразия.\n\n3.Российская Федерация оказывает поддержку соотечественникам, проживающим за рубежом, в осуществлении их прав, обеспечении защиты их интересов и сохранении общероссийской культурной идентичности.","article_title":"Статья 69","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"152978aa385986167631b1e88d7753381156d5848bc6c31e6b6901e3da683824"},{"code_id":"KONST_RF","article_number":"7","version_date":"1993-12-12","article_text":"1.Российская Федерация — социальное государство, политика которого направлена на создание условий, обеспечивающих достойную жизнь и свободное развитие человека.\n\n2.В Российской Федерации охраняются труд и здоровье людей, устанавливается гарантированный минимальный размер оплаты труда, обеспечивается государственная поддержка семьи, материнства, отцовства и детства, инвалидов и пожилых граждан, развивается система социальных служб, устанавливаются государственные пенсии, пособия и иные гарантии социальной защиты.","article_title":"Статья 7","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"552cf799d6391634e62c604d9c7156910cb2125d0dd7af37fec80f0f24382a03"}]$law7d0046$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
